using System.Globalization;
using System.Text.Json;
using System.Text.RegularExpressions;
namespace LeoLauncher;
static class UiLanguageTests
{
    static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(var nested in Walk(child))yield return nested;}
    public static void Run(string path){Directory.CreateDirectory(Path.GetDirectoryName(path)!);using var host=new Form{Opacity=0,ShowInTaskbar=false};host.Shown+=async(_,_)=>{var c=new Dictionary<string,bool>();try{await Check(Path.GetDirectoryName(path)!,c);File.WriteAllText(path,JsonSerializer.Serialize(new{ok=c.Values.All(x=>x),checks=c,network_requests=0,external_apps_started=0},new JsonSerializerOptions{WriteIndented=true}));}catch(Exception e){File.WriteAllText(path,JsonSerializer.Serialize(new{ok=false,error=e.ToString(),checks=c}));}finally{UiLanguage.Configure("zh-CN");host.Close();}};Application.Run(host);}
    static async Task Check(string folder,Dictionary<string,bool> c)
    {
        string culture=CultureInfo.CurrentCulture.Name;var old=new Preferences();c["old_configuration_defaults_to_chinese"]=old.InterfaceLanguage=="zh-CN"&&JsonSerializer.Deserialize<Preferences>("{}")!.InterfaceLanguage=="zh-CN";c["setting_round_trip"]=JsonSerializer.Deserialize<Preferences>(JsonSerializer.Serialize(withLanguage()))!.InterfaceLanguage=="en";
        Preferences withLanguage(){old.InterfaceLanguage="en";return old;}
        bool rejected=false;try{UiLanguage.Validate("other");}catch(ArgumentException){rejected=true;}c["unknown_language_rejected"]=rejected;
        using(var form=new Form()){var label=new Label{Text="设置"};var user=new Label{Text="设置"};UiLanguage.Preserve(user);var input=new TextBox{Text="保存",PlaceholderText="搜索便签…"};var rich=new RichTextBox{Text="删除"};form.Controls.AddRange([label,user,input,rich]);form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();UiLanguage.Attach(form);UiLanguage.Configure("en");c["static_label_translated"]=label.Text=="Settings";c["business_data_and_editors_preserved"]=user.Text=="设置"&&input.Text=="保存"&&rich.Text=="删除";c["placeholder_translated"]=input.PlaceholderText=="Search notes…";label.Text="重试";c["dynamic_label_translated"]=label.Text=="Retry";var added=new Button{Text="关闭"};form.Controls.Add(added);c["new_controls_translated"]=added.Text=="Close";UiLanguage.Configure("zh-CN");c["switch_back_restores_original_strings"]=label.Text=="重试"&&added.Text=="关闭"&&input.PlaceholderText=="搜索便签…";}
        UiLanguage.Configure("en");c["repeated_markers_are_bounded"]=UiLanguage.T(string.Concat(Enumerable.Repeat("✓ ",2000))+"设置").Length>0;c["data_in_status_prefixes_stays_verbatim"]=UiLanguage.T("搜索口令：准备看球")=="Search command: 准备看球"&&UiLanguage.T("点播：保存")=="Play: 保存"&&UiLanguage.T("已切换：保存")=="Switched: 保存";c["formatted_counts_translate"]=UiLanguage.T("模型请求 3 次")=="Model requests 3"&&UiLanguage.T("＋ 添加网址 2")=="＋ Add link 2"&&UiLanguage.T("模型请求 3 次 · 完整回复 2 次")=="Model requests 3 · Completed replies 2";c["no_execution_or_global_culture_change"]=QuickRouter.Route("打开邮箱").Value=="mail_client_open"&&CultureInfo.CurrentCulture.Name==culture;c["custom_names_untouched"]=new ComboChoice("保存","fixture").ToString()=="保存";c["ui_choices_translate_without_changing_values"]=new ComboChoice("保存","fixture",true) is{} choice&&choice.Value=="fixture"&&choice.ToString()=="Save";
        using(var menu=new ContextMenuStrip()){var item=new ToolStripMenuItem("清单与记录");menu.Items.Add(item);UiLanguage.Attach(menu);c["menus_have_stable_source_and_translated_text"]=item.Text=="Planner & notes"&&UiLanguage.Source(item)=="清单与记录";UiLanguage.Configure("zh-CN");UiLanguage.Attach(menu);c["menu_switch_back_uses_source"]=item.Text=="清单与记录";}
        UiLanguage.Configure("en");using(var branded=new Form()){var caption=new Label{Text="问 Leo"};branded.Controls.Add(caption);branded.Show();UiLanguage.Attach(branded);UiTheme.Configure("83","Milo");c["pet_rename_survives_english_ui"]=caption.Text=="Ask Milo";UiLanguage.Configure("zh-CN");c["pet_rename_survives_language_round_trip"]=caption.Text=="问 Milo";UiTheme.Configure("83","Leo");}
        UiLanguage.Configure("en");var preferences=new Preferences{ApplicationIndexing=false};string before=JsonSerializer.Serialize(preferences);var residual=new Dictionary<string,string[]>();
        Preferences? saved=null;using(var settings=new SettingsForm(preferences,(next,_)=>saved=next,()=>{},true)){await Preview(settings,"settings");c["settings_has_language_selector"]=Walk(settings).OfType<ComboBox>().Any(x=>x.Items.Contains("English"));c["settings_has_english_save"]=Walk(settings).OfType<Button>().Any(x=>x.Text=="Save settings");var selector=Walk(settings).OfType<ComboBox>().Single(x=>x.Items.Contains("English"));selector.SelectedIndex=1;Walk(settings).OfType<Button>().Single(x=>x.Text=="Save settings").PerformClick();c["save_carries_interface_language_in_configuration"]=saved?.InterfaceLanguage=="en";}
        using(var chat=new ChatForm(true)){await Preview(chat,"chat");c["chat_has_english_composer"]=Walk(chat).OfType<Button>().Any(x=>x.Text=="Send ↗");chat.ClientSize=new(500,410);await Task.Delay(40);chat.ClientSize=new(900,650);await Task.Delay(40);c["english_chat_can_resize"]=!chat.IsDisposed;}
        using(var todos=new TodoForm(true,new TodoStore(null)))await Preview(todos,"planner");
        using(var football=new FootballForm(true))await Preview(football,"football");
        using(var music=new MusicForm(true))await Preview(music,"music");
        using(var media=new MediaForm((_,_,_)=>Task.FromResult(""),true))await Preview(media,"media");
        using(var apps=new ApplicationEditor(null,null,null))await Preview(apps,"app-editor");
        using(var mail=new MailClientForm(preferences,_=>{},()=>Task.CompletedTask,true))await Preview(mail,"mail");
        var custom=new LocalApplication(Guid.NewGuid().ToString("N"),"保存",Environment.ProcessPath!);using(var editor=new QuickEntrySettingsForm(new Preferences{ApplicationModules=[custom]},custom.Id)){await Preview(editor,"custom-shortcut");c["custom_shortcut_title_is_not_ui_text"]=Walk(editor).OfType<Label>().Any(l=>l.Text=="保存");}
        using(var icons=new BuiltinIconPicker())await Preview(icons,"icons");
        using(var pet=new PetForm(new Preferences{ApplicationIndexing=false,InterfaceLanguage="en"},true)){pet.Show();UiLanguage.Attach(pet);var menu=pet.ContextMenuStrip!;UiLanguage.Attach(menu);c["pet_menu_keeps_stable_sources"]=menu.Items.OfType<ToolStripMenuItem>().Any(i=>UiLanguage.Source(i)=="清单与记录"&&i.Text=="Planner & notes");pet.Close();}
        using(var bad=new Form()){bad.Show();UiLanguage.RefreshOnChange(bad,()=>throw new IOException("isolated language view"));UiLanguage.Configure("zh-CN");UiLanguage.Configure("en");c["single_view_refresh_failure_isolated"]=UiLanguage.Current=="en";}
        File.WriteAllText(Path.Combine(folder,"remaining-text.json"),JsonSerializer.Serialize(residual,new JsonSerializerOptions{WriteIndented=true}));
        c["language_switch_preserves_original_preferences"]=JsonSerializer.Serialize(preferences)==before;
        async Task Preview(Form form,string name){form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();UiLanguage.Attach(form);await Task.Delay(25);residual[name]=Walk(form).Where(x=>x is Label or ButtonBase).Select(x=>x.Text).Where(t=>Regex.IsMatch(t,"[一-鿿]")).Distinct().ToArray();using var png=new Bitmap(form.Width,form.Height);form.DrawToBitmap(png,new(Point.Empty,form.Size));png.Save(Path.Combine(folder,name+"-en.png"));}
    }
}
